import { S, allRuns, bgLum, bgOf, byId, changedOthers, colorsSame, contrast, deckText, hexOf, images, isGreen, isRed, layoutOf, lum, majority, newFigures, notesOf, points, posOf, runs, slideBgsSame, texts, themeSame, wordCount, words } from './ai-full-qa-lib.mjs'

/**
 * The cases of the full AI-edit QA. `real` = typed by a real person in our editor (exact words, replayed on a copy of THEIR deck as it was before they chatted).
 * `catalogue` = an everyday request from docs/AI_EDIT_HONESTY_AND_SCENARIOS.md section 6 that we say the assistant handles.
 * expect: 'do' (the change must be fully on the saved deck), 'ask' (one question, nothing changed), 'refuse' (said plainly, nothing changed, no credits), 'do-or-ask'.
 * check(ctx) returns a list of problems; empty = the request was done 100%. ctx = { b: deck before, a: deck after, r: last reply, turns, A: active slide id }
 */
const P = (cond, msg) => (cond ? [] : [msg])
const others = (b, a, ids) => { const c = changedOthers(b, a, ids); return P(!c.length, `other slides changed: ${c.join(', ')}`) }
const nothingChanged = ({ b, a }) => [...P(themeSame(b, a), 'theme changed'), ...P(b.slides.length === a.slides.length, 'slide count changed'), ...others(b, a, [])]
const noCredits = ({ turns }) => P(turns.every((t) => !t.creditsCharged), `credits charged: ${turns.map((t) => t.creditsCharged).join(',')}`)
const lightDeck = (d) => d.slides.filter((s) => (bgLum(d, s) ?? 0) > 170).length / d.slides.length
const darkDeck = (d) => d.slides.filter((s) => (bgLum(d, s) ?? 255) < 110).length / d.slides.length
/** every text run on these slides reads on its slide background (contrast 3:1 or better) */
const readable = (d, slides) => slides.flatMap((s) => runs(d, s).filter((x) => { const c = contrast(x.color, bgOf(d, s)); return c !== null && c < 3 }).map((x) => `slide ${posOf(d, s.id)} "${x.text.slice(0, 24)}" ${x.color} on ${bgOf(d, s)}`)).slice(0, 4)
const newSlides = (b, a) => a.slides.filter((s) => !byId(b, s.id))
const imgSig = (s) => JSON.stringify(images(s).map((e) => [e.src, e.x, e.y, e.width, e.height]))
const pictureAdded = (b, a, n) => { const sb = S(b, n), sa = byId(a, sb.id) ?? S(a, n); return images(sa).length > images(sb).length || (sa.background?.type === 'image' && sb.background?.type !== 'image') || imgSig(sa) !== imgSig(sb) }
const thankYouAdded = ({ b, a }) => { const n = newSlides(b, a); const last = a.slides.at(-1); const bgMaj = majority(b.slides.map((s) => bgOf(b, s))); return [...P(n.length === 1, `${n.length} slides added (wanted 1)`), ...P(n[0] && last.id === n[0].id, 'the new slide is not at the end'), ...P(n[0] && /thank/i.test(words(n[0])), `the new slide does not say thank you: "${n[0] ? words(n[0]).slice(0, 60) : ''}"`), ...P(!n[0] || bgOf(a, n[0]) === bgMaj || (bgLum(a, n[0]) !== null && Math.abs(bgLum(a, n[0]) - lum(bgMaj)) < 40), `the new slide background ${n[0] ? bgOf(a, n[0]) : ''} does not match the other slides (${bgMaj})`), ...(n[0] ? P(!readable(a, [n[0]]).length, `text not readable: ${readable(a, [n[0]]).join('; ')}`) : []), ...others(b, a, [])] }
const layoutKept = (b, a, n) => P(layoutOf(byId(a, S(b, n).id)) === layoutOf(S(b, n)), `layout changed ${layoutOf(S(b, n))} → ${layoutOf(byId(a, S(b, n).id))}`)
const rewritten = (b, a, n) => P(words(byId(a, S(b, n).id)) !== words(S(b, n)), `slide ${n} words are unchanged`)
const more = (b, a, n, f = 1.15) => { const w0 = wordCount(S(b, n)), w1 = wordCount(byId(a, S(b, n).id)); return P(w1 >= w0 * f, `slide ${n} has ${w0} → ${w1} words (wanted more)`) }
const noInvented = (b, a) => { const f = newFigures(deckText(b), deckText(a)); return P(!f.length, `new figures not in the deck: ${f.slice(0, 6).join(', ')}`) }
const el = (d, slideId, id) => byId(d, slideId)?.elements?.find((e) => e.id === id)

/** only the named words of one text box got the style: every other word looks as before, the words are unchanged, no other slide changed */
const wordCheck = (b, a, n, role, words, has) => {
  const id = S(b, n).id, before = S(b, n).elements, after = byId(a, id).elements
  const txt = (e) => e.paragraphs.map((p) => p.runs.map((r) => r.text).join('')).join('\n')
  const target = after.find((e) => e.type === 'text' && e.role === role && txt(e).toLowerCase().includes(words.toLowerCase()))
  if (!target) return [`no ${role} with "${words}" after`]
  const old = before.find((e) => e.id === target.id)
  const styled = target.paragraphs.flatMap((p) => p.runs).filter(has)
  const rest = target.paragraphs.flatMap((p) => p.runs).filter((r) => !has(r)).map((r) => r.text).join('')
  return [...P(styled.length && styled.map((r) => r.text).join('').toLowerCase().replace(/\s+/g, ' ').includes(words.toLowerCase()), `the words did not get the style: ${JSON.stringify(target.paragraphs)}`),
    ...P(styled.map((r) => r.text).join('').length <= words.length * 2, `more than the words got the style: ${JSON.stringify(styled.map((r) => r.text))}`),
    ...P(txt(target) === txt(old), 'the words themselves changed'), ...P(!rest.toLowerCase().includes(words.toLowerCase()), 'an occurrence was missed'),
    ...P(after.filter((e) => e.id !== target.id).every((e) => JSON.stringify(e) === JSON.stringify(before.find((x) => x.id === e.id))), 'other objects on the slide changed'), ...others(b, a, [id])]
}
/** a small table for the merge cases (W110-W113); `merges` = areas it starts with */
const qaTable = (merges) => ({ id: 'qatable', type: 'table', x: 1000, y: 520, width: 820, height: 380, rotation: 0, locked: false, zIndex: 20, opacity: 1, header: ['Region', 'Q1', 'Q2', 'Q3'], rows: [['North', '10', '14', '9'], ['South', '6', '8', '12'], ['East', '5', '7', '8']], ...(merges ? { merges } : {}) })
/** a table's merged areas compared by value (the database keeps object keys in its own order) */
const areasOf = (t) => JSON.stringify((t?.merges ?? []).map((x) => [x.row, x.column, x.rows, x.columns]))
/** the live account's saved brand for the slide-brand cases (W114-W116): one default kit, the same every run */
const liveKit = async ({ A, API }) => {
  const H = { origin: 'http://localhost:3001' }
  for (const k of (await (await A.ctx.request.get(`${API}/api/v1/brand/kits`, { headers: H })).json()).data?.kits ?? []) await A.ctx.request.delete(`${API}/api/v1/brand/kits/${k.id}`, { headers: H })
  const r = await A.ctx.request.post(`${API}/api/v1/brand/kits`, { headers: H, data: { name: 'Acme Live', primary: '#E4572E', accent: '#17BEBB', headingFont: 'Playfair Display', bodyFont: 'Inter', isDefault: true } })
  if (!r.ok()) throw new Error(`kit ${r.status()} ${(await r.text()).slice(0, 200)}`)
}
/** a kit plus one theme made from it, in the deck's own template, dark (brand/themes.ts) */
const liveKitTheme = async (c) => {
  await liveKit(c)
  const H = { origin: 'http://localhost:3001' }
  const kit = (await (await c.A.ctx.request.get(`${c.API}/api/v1/brand/kits`, { headers: H })).json()).data.kits[0]
  const r = await c.A.ctx.request.post(`${c.API}/api/v1/brand/themes`, { headers: H, data: { kitId: kit.id, designId: c.doc.theme.templateId, mode: 'dark', name: 'Acme Night' } })
  if (!r.ok()) throw new Error(`theme ${r.status()} ${(await r.text()).slice(0, 200)}`)
}
